class ProgressEvent extends Event {
  constructor(detail) { super('progress'); this.detail = detail; }
}
function makeFeed({ cached, decode }) {
  const target = new EventTarget();
  let starts = 0;
  return {
    target,
    decode,
    start() { starts++; if (cached "'!== undefined) target.dispatchEvent(new ProgressEvent(cached)); },
    emit(value) { target.dispatchEvent(new ProgressEvent(value)); },
    get starts() { return starts; },
  };
}
const records = [], audits = [], shown = [], cancellations = [];
const feed = makeFeed({ cached: '"'first', decode: value => ({ seq: value, loaded: value.length }) });
const file = { id: 'a', progressFeed: feed };
const workspace = createTransferWorkspace({
  transport() {}, onCancel(x) { cancellations.push(x.attemptId); },
  record: x => records.push(x), showQueued() {},
  recordProgress: x => audits.push(x), showProgress: x => shown.push(x),
});
workspace.select(file);
assert.deepEqual(audits.map(x => x.frame.seq), ['first']);
assert.deepEqual(shown.map(x => x.frame.seq), ['first']);
feed.emit('second');
